import{_ as a,a as s,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 单元 1 复习与自测 · 第10–18课","description":"L1–L24 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 1 复习与自测 · 第10–18课","description":"L1–L24 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-01/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 1 复习与自测","summary":"L1–L24 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 1 复习与自测 · 第1–9课","link":"/life/english/new-concept/book-2/unit-01/review-part-01"},"next":{"text":"第二册：实践与进步 · 单元 1 复习与自测 · 第19–24课","link":"/life/english/new-concept/book-2/unit-01/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 1 复习与自测 · 第1–9课","link":"/life/english/new-concept/book-2/unit-01/review-part-01"},"next":{"text":"第二册：实践与进步 · 单元 1 复习与自测 · 第19–24课","link":"/life/english/new-concept/book-2/unit-01/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/review-part-02.md","filePath":"life/english/new-concept/book-2/unit-01/review-part-02.md"}'),n={name:"life/english/new-concept/book-2/unit-01/review-part-02.md"};function r(l,e,i,h,p,d){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-1-复习与自测-·-第10–18课" tabindex="-1">第二册：实践与进步 · 单元 1 复习与自测 · 第10–18课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-1-复习与自测-·-第10–18课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 1 复习与自测 · 第10–18课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-01/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-10-·-被动语态与信息重点" tabindex="-1">Lesson 10 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-10-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 10 · 被动语态与信息重点 {#lesson-10-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The old guitar was repaired by a local technician.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>填 repair 的形式：The guitar was ___ yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> repaired</p><p><strong>解析：</strong> 被动语态要求 be 加过去分词。</p></details><p><strong>表达迁移：</strong> 用三句说明一件旧物的来源、损坏和修理结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The old guitar was repaired by a local technician. One string had broken during practice. It now sounds clear again.</p><p>第一句的组织方式：The old guitar 是承受动作的主语，was repaired 是一般过去时被动，by 短语指出执行者。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：The guitar was belonged to me 错误；belong 表归属，用 The guitar belonged to me。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-010">回看本课</a></p><h2 id="lesson-11-·-现在完成时与过去时间" tabindex="-1">Lesson 11 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-11-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 11 · 现在完成时与过去时间 {#lesson-11-·-现在完成时与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Ravi has lent me his bicycle for the weekend.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>填 lend 的过去分词：Ravi has ___ me his bicycle.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lent</p><p><strong>解析：</strong> lend 的过去式和过去分词都是 lent。</p></details><p><strong>表达迁移：</strong> 写一次互助经历，明确谁借入、谁借出，以及归还安排。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Ravi has lent me his bicycle for the weekend. I helped him repair a shelf last week. We try to return things on time.</p><p>第一句的组织方式：Ravi 是借出者，has lent 是完成时，me 是接收者，for the weekend 说明借用时段。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：borrow me a bicycle 通常不表示借给我；应说 lend me a bicycle。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-011">回看本课</a></p><h2 id="lesson-12-·-将来表达与安排" tabindex="-1">Lesson 12 · 将来表达与安排 <a class="header-anchor" href="#lesson-12-·-将来表达与安排" aria-label="Permalink to &quot;Lesson 12 · 将来表达与安排 {#lesson-12-·-将来表达与安排}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Our neighbour is sailing to the island on Friday.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>填 on/at：The boat leaves ___ Friday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> on</p><p><strong>解析：</strong> 星期几前使用 on。</p></details><p><strong>表达迁移：</strong> 写一个送别小段落，包含出发安排、礼物和到达后的行动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our neighbour is sailing to the island on Friday. We have bought a small gift for her. She will call us when she arrives.</p><p>第一句的组织方式：is sailing 是现在进行时表将来安排，on Friday 明确日期，to the island 表示目的地。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：sail to the island 表示去岛上；sail across the island 不符合船只在水面航行的通常语境。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-012">回看本课</a></p><h2 id="lesson-13-·-将来进行时与过程" tabindex="-1">Lesson 13 · 将来进行时与过程 <a class="header-anchor" href="#lesson-13-·-将来进行时与过程" aria-label="Permalink to &quot;Lesson 13 · 将来进行时与过程 {#lesson-13-·-将来进行时与过程}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> At seven tomorrow, the band will be rehearsing in the hall.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>补全将来进行时：The band will ___ rehearsing at seven.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> 将来进行时结构为 will be doing。</p></details><p><strong>表达迁移：</strong> 写三句演出日程，分别交代排练、开门和开演时间。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>At seven tomorrow, the band will be rehearsing in the hall. The doors will open at eight. The first song will begin at half past eight.</p><p>第一句的组织方式：At seven tomorrow 建立未来参照点，will be rehearsing 表示该时刻正在进行的活动，in the hall 是地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：will rehearsing 缺少 be；will be rehearse 的动词形式也不对。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-013">回看本课</a></p><h2 id="lesson-14-·-过去进行时与叙事背景" tabindex="-1">Lesson 14 · 过去进行时与叙事背景 <a class="header-anchor" href="#lesson-14-·-过去进行时与叙事背景" aria-label="Permalink to &quot;Lesson 14 · 过去进行时与叙事背景 {#lesson-14-·-过去进行时与叙事背景}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I was looking for the station when a cyclist offered help.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>选 was/were：I ___ looking for the station.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> was</p><p><strong>解析：</strong> I 在过去进行时中配 was。</p></details><p><strong>表达迁移：</strong> 模拟问路后的回忆，说明困难、对方如何帮助以及最终结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I was looking for the station when a cyclist offered help. He spoke slowly and pointed to a bridge. I finally understood which way to go.</p><p>第一句的组织方式：I was looking 是持续背景，when 引出 offered；offer help 中 help 是不可数名词。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：explain me the route 不符合常见搭配；用 explain the route to me。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-014">回看本课</a></p><h2 id="lesson-15-·-间接引语与视角转换" tabindex="-1">Lesson 15 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-15-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 15 · 间接引语与视角转换 {#lesson-15-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The manager told Hana that her work was excellent.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>选 said/told：The manager ___ Hana that her work was excellent.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> told</p><p><strong>解析：</strong> 后面直接接听者 Hana，使用 told。</p></details><p><strong>表达迁移：</strong> 转述一次出乎意料的好消息，说明原来的担心和实际内容。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The manager told Hana that her work was excellent. Hana had expected a complaint. Instead, she was offered a new project.</p><p>第一句的组织方式：told 的宾语是 Hana，that 引出所说内容；her 指 Hana，was 在过去视角下转述评价。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：said Hana that 错误；说给某人听可用 said to Hana 或 told Hana。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-015">回看本课</a></p><h2 id="lesson-16-·-情态动词的意义与形式" tabindex="-1">Lesson 16 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-16-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 16 · 情态动词的意义与形式 {#lesson-16-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Could you move your car away from the entrance, please?</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>补全请求：Could you ___ your car?（move/moving）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> move</p><p><strong>解析：</strong> 情态动词 could 后使用动词原形。</p></details><p><strong>表达迁移：</strong> 写一条三句停车提醒：提出请求、解释原因、提供替代位置。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Could you move your car away from the entrance, please? The sign says that deliveries use this gate. There is a free parking space across the road.</p><p>第一句的组织方式：Could 位于主语 you 前形成问句，后接 move 原形；away from 引出应远离的位置，please 缓和语气。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Could you to move 多了 to；could 是情态动词，后接原形。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-016">回看本课</a></p><h2 id="lesson-17-·-一般现在时与习惯" tabindex="-1">Lesson 17 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-17-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 17 · 一般现在时与习惯 {#lesson-17-·-一般现在时与习惯}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My aunt always looks cheerful before a performance.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>选 cheerful/cheerfully：She looks ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> cheerful</p><p><strong>解析：</strong> 系动词 looks 后用形容词作表语。</p></details><p><strong>表达迁移：</strong> 介绍一位有活力的成年人，描述习惯与精神状态，不凭外表推断年龄。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My aunt always looks cheerful before a performance. She practises with a community theatre group. Nobody in the group asks her age.</p><p>第一句的组织方式：My aunt 是主语，looks 是系动词，cheerful 是表语；always 表示频率，不修饰形容词程度。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：looks cheerfully 若没有其他内容不能表达“看起来愉快”；此处用 cheerful。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-017">回看本课</a></p><h2 id="lesson-18-·-一般现在时与习惯" tabindex="-1">Lesson 18 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-18-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 18 · 一般现在时与习惯 {#lesson-18-·-一般现在时与习惯}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Our dog often hides my bag under the sofa.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>填 hide 的形式：Our dog often ___ my bag.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> hides</p><p><strong>解析：</strong> dog 是单数第三人称主语。</p></details><p><strong>表达迁移：</strong> 描述一个宠物或家人的重复习惯，再讲一次例外。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our dog often hides my bag under the sofa. Yesterday I searched the hallway first. I found the bag beside his blanket.</p><p>第一句的组织方式：often 放在实义动词 hides 前；my bag 是宾语，under the sofa 是地点，第三人称单数动词加 -s。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Does the dog hides 错误；does 出现后使用 hide。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-018">回看本课</a></p>',76)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
